param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'numberformatinfo-native-digits-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json;$property=[Globalization.NumberFormatInfo].GetProperty('NativeDigits')
function Decode($Encoded){if([object]::ReferenceEquals($Encoded,$null)){return ,$null};$a=[string[]]::new($Encoded.Count);for($i=0;$i -lt $a.Length;$i++){if(-not [object]::ReferenceEquals($Encoded[$i],$null)){$a[$i]=-join [char[]][int[]]$Encoded[$i]}};return ,$a}
function Normalize($Array){if([object]::ReferenceEquals($Array,$null)){return ,$null};$values=[Collections.Generic.List[object]]::new();foreach($s in $Array){if([object]::ReferenceEquals($s,$null)){$values.Add($null)}else{$values.Add([int[]][char[]]$s)}};return ,$values.ToArray()}
function Digits($N){$a=[string[]]$property.GetValue($N);return ,(Normalize $a)}
function Failure($Record){$e=$Record.Exception;while($e -is [Reflection.TargetInvocationException] -or $e -is [Management.Automation.MethodInvocationException]){$e=$e.InnerException};return [ordered]@{ok=$false;exception=$e.GetType().FullName;messageUnits=[int[]][char[]]$e.Message;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})}}
$rows=[Collections.Generic.List[object]]::new()
for($index=0;$index -lt $plan.profiles.Count;$index++){foreach($mode in $plan.modes){$original=[Globalization.NumberFormatInfo]::new();$readonly=[Globalization.NumberFormatInfo]::ReadOnly($original);switch($mode){'mutable'{$target=$original};'readonly'{$target=$readonly};'clone'{$target=[Globalization.NumberFormatInfo]$readonly.Clone()};'invariant'{$target=[Globalization.NumberFormatInfo]::InvariantInfo}};$inputDigits=Decode $plan.profiles[$index];$before=Digits $target
 try{$property.SetValue($target,$inputDigits);$result=[ordered]@{ok=$true}}catch{$result=Failure $_};$inputAfter=Normalize $inputDigits;$afterSet=Digits $target;$copy=[Globalization.NumberFormatInfo]$target.Clone();$view=[Globalization.NumberFormatInfo]::ReadOnly($target);$cloneBefore=Digits $copy;$readonlyBefore=Digits $view
 if(-not [object]::ReferenceEquals($inputDigits,$null) -and $inputDigits.Length -gt 0){$inputDigits[0]='caller!'};$afterCaller=Digits $target;$cloneAfterCaller=Digits $copy;$readonlyAfterCaller=Digits $view
 $getter=[string[]]$property.GetValue($target);$second=[string[]]$property.GetValue($target);$distinct=-not [object]::ReferenceEquals($getter,$second);$getter[1]='getter!';$afterGetter=Digits $target
 $rows.Add([ordered]@{profile=$index;mode=$mode;before=$before;result=$result;inputAfter=$inputAfter;afterSet=$afterSet;cloneBefore=$cloneBefore;readonlyBefore=$readonlyBefore;afterCaller=$afterCaller;cloneAfterCaller=$cloneAfterCaller;readonlyAfterCaller=$readonlyAfterCaller;distinctGetters=$distinct;afterGetter=$afterGetter;originalAfter=(Digits $original);targetReadOnly=$target.IsReadOnly;cloneReadOnly=$copy.IsReadOnly;viewReadOnly=$view.IsReadOnly})
}}
if($rows.Count -ne 180){throw 'Wrong native digit matrix'}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();culture='Invariant';rows=$rows.ToArray();qualification='SELECTED_NATIVE_DIGITS_VALIDATION_AND_NATIVE_ARRAY_ALIASING_ONLY; ALL_UNICODE_VERSIONS_NUMERIC_DIGIT_SUBSTITUTION_CULTURES_FULL_METADATA_SERIALIZATION_AND_TASK_ACCEPTANCE_OPEN'};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 26 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output 'PASS NativeDigits reference: 45 profiles, 180 cases'
